using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;
namespace MyFundex.Subscription;
public sealed class Plan:EntityBase{public Guid PlanId{get;set;}public string Code{get;set;}="";public string Name{get;set;}="";public string? Description{get;set;}}
public sealed class PlanVersion:EntityBase{public Guid PlanVersionId{get;set;}public long PlanInternalId{get;set;}public int VersionNumber{get;set;}public decimal ChallengeCapital{get;set;}public decimal RegistrationFee{get;set;}public string Status{get;set;}="Draft";public DateTimeOffset EffectiveFrom{get;set;}public DateTimeOffset? EffectiveTo{get;set;}}
public sealed class PlanStageDefinition:EntityBase{public Guid StageId{get;set;}public long PlanVersionInternalId{get;set;}public int StageNumber{get;set;}public string Name{get;set;}="";public decimal StartingCapital{get;set;}public Guid PolicySetId{get;set;}public bool RequiredForCompletion{get;set;}=true;}
public sealed class UserSubscription:EntityBase{public Guid SubscriptionId{get;set;}public long UserInternalId{get;set;}public long PlanInternalId{get;set;}public long PlanVersionInternalId{get;set;}public string Status{get;set;}="PendingPayment";public DateTimeOffset SubscribedAt{get;set;}public DateTimeOffset? ActivatedAt{get;set;}public DateTimeOffset? CompletedAt{get;set;}public DateTimeOffset? ExpiredAt{get;set;}}
public sealed class SubscriptionDbContext(DbContextOptions<SubscriptionDbContext> o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<Plan>Plans=>Set<Plan>();public DbSet<PlanVersion>PlanVersions=>Set<PlanVersion>();public DbSet<PlanStageDefinition>Stages=>Set<PlanStageDefinition>();public DbSet<UserSubscription>Subscriptions=>Set<UserSubscription>();protected override void OnModelCreating(ModelBuilder m) => ConfigureModel(m); public static void ConfigureModel(ModelBuilder m) {m.HasDefaultSchema("subscription");ConfigureEntity(m.Entity<Plan>());ConfigureEntity(m.Entity<PlanVersion>());ConfigureEntity(m.Entity<PlanStageDefinition>());ConfigureEntity(m.Entity<UserSubscription>());m.Entity<Plan>().HasIndex(x=>x.PlanId).IsUnique();m.Entity<Plan>().HasIndex(x=>x.Code).IsUnique().HasFilter("\"IsDeleted\" = false");m.Entity<PlanVersion>().HasIndex(x=>new{x.PlanInternalId,x.VersionNumber}).IsUnique().HasFilter("\"IsDeleted\" = false");m.Entity<UserSubscription>().HasIndex(x=>x.SubscriptionId).IsUnique();}}
public static class SubscriptionModule{public static IServiceCollection AddSubscriptionModule(this IServiceCollection s,string cs){s.AddDbContext<SubscriptionDbContext>(o=>o.UseNpgsql(cs));return s;}}
